import{_ as o,o as e,c as d,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Privacidade e tratamento de dados","description":"","frontmatter":{"title":"Privacidade e tratamento de dados","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/privacidade"}]]},"headers":[],"relativePath":"privacidade.md","filePath":"privacidade.md"}'),s={name:"privacidade.md"};function t(i,a,n,c,u,l){return e(),d("div",null,a[0]||(a[0]=[r('<h1 id="privacidade-e-tratamento-de-dados" tabindex="-1">Privacidade e tratamento de dados <a class="header-anchor" href="#privacidade-e-tratamento-de-dados" aria-label="Permalink to &quot;Privacidade e tratamento de dados&quot;">​</a></h1><p>Esta página explica, em linguagem direta, o que o eploc faz com os dados que passam pela sua tela. O documento oficial é a <a href="https://eploc.com.br/privacidade" target="_blank" rel="noreferrer">Política de privacidade do eploc</a>; em caso de dúvida, vale o que está nela.</p><h2 id="resumo" tabindex="-1">Resumo <a class="header-anchor" href="#resumo" aria-label="Permalink to &quot;Resumo&quot;">​</a></h2><ul><li>O eploc roda <strong>inteiramente no seu navegador</strong>. O desenvolvedor não opera servidor e não recebe nenhum dado de processo, de parte, de usuário ou de configuração.</li><li>Não há publicidade, rastreamento nem venda de dados.</li><li>O único envio de dados para fora do navegador que depende de você é o <a href="./geral/backup-google-drive">backup no Google Drive</a>, que é <strong>opcional</strong> e vem <strong>desligado</strong>.</li></ul><h2 id="o-que-o-eploc-le" tabindex="-1">O que o eploc lê <a class="header-anchor" href="#o-que-o-eploc-le" aria-label="Permalink to &quot;O que o eploc lê&quot;">​</a></h2><p>Para funcionar, o eploc lê o conteúdo das páginas do eproc, SEI, RUPE e TJMG <strong>enquanto você as usa</strong> (números de processo, nomes de partes, eventos, documentos listados etc.), só para organizar e exibir essas informações na sua tela. Ele não lê páginas de outros sites.</p><h2 id="o-que-nunca-sai-do-seu-navegador" tabindex="-1">O que nunca sai do seu navegador <a class="header-anchor" href="#o-que-nunca-sai-do-seu-navegador" aria-label="Permalink to &quot;O que nunca sai do seu navegador&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dado</th><th>Onde fica</th></tr></thead><tbody><tr><td>Conteúdo das páginas do eproc, SEI, RUPE e TJMG</td><td>Só na página aberta. Não é copiado para lugar nenhum.</td></tr><tr><td>Dados de processos lidos para os <a href="./funcionalidades/eproc-modelos-mensagem">modelos de mensagem</a> (número, classe, nomes das partes)</td><td>Neste computador, por até 24 horas, fora dos backups.</td></tr><tr><td>Descrições de eventos de processos migrados (<a href="./funcionalidades/eproc-restaurar-descricao-eventos-migrados">Restaurar descrição</a>)</td><td>Neste computador, por 30 minutos, fora dos backups.</td></tr><tr><td>Nomes de usuários associados a matrículas (<a href="./funcionalidades/eproc-exibir-nomes-usuarios">Exibir nomes</a>)</td><td>Neste computador, fora dos backups.</td></tr><tr><td>Histórico de alertas (<a href="./funcionalidades/eproc-alertas-inline">Alertas menos intrusivos</a>)</td><td>Neste computador, últimos 7 dias, fora dos backups.</td></tr><tr><td>Valor anterior das colunas do <a href="./funcionalidades/eproc-monitor-relatorio">Monitor de Relatórios</a></td><td>Cifrado, só neste computador, nunca em backups. Desligado por padrão: sem essa opção, o eploc guarda só uma impressão digital (hash) dos valores.</td></tr><tr><td>Configuração de múltiplos monitores</td><td>Neste computador.</td></tr><tr><td>Senhas</td><td>O eploc não lê nem guarda senhas. O recurso <a href="./funcionalidades/eproc-login-gerenciador-senhas">Permitir credenciais salvas</a> só deixa o gerenciador de senhas do próprio navegador funcionar.</td></tr></tbody></table><h2 id="o-que-fica-guardado-nas-configuracoes-do-navegador" tabindex="-1">O que fica guardado nas configurações do navegador <a class="header-anchor" href="#o-que-fica-guardado-nas-configuracoes-do-navegador" aria-label="Permalink to &quot;O que fica guardado nas configurações do navegador&quot;">​</a></h2><p>Suas configurações e os dados que você mesmo cria no eploc (contatos de e-mail, modelos de mensagem, destaques, processos monitorados, pastas, favoritos, perfil favorito do login, rótulos aprendidos do CPHA etc.) ficam no armazenamento da extensão, no seu perfil do Chrome ou do Edge.</p><p>Parte das configurações usa o armazenamento <strong>sincronizado</strong> do navegador. Se a sincronização do Chrome ou do Edge estiver ligada no seu perfil, o próprio navegador leva essas configurações para os outros computadores em que você usa a mesma conta do navegador (Google ou Microsoft), como faz com as configurações de qualquer extensão.</p><p>Você pode apagar tudo a qualquer momento removendo a extensão.</p><h2 id="quando-algum-dado-sai-do-navegador" tabindex="-1">Quando algum dado sai do navegador <a class="header-anchor" href="#quando-algum-dado-sai-do-navegador" aria-label="Permalink to &quot;Quando algum dado sai do navegador&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situação</th><th>O que é enviado</th><th>Para onde</th></tr></thead><tbody><tr><td><a href="./geral/backup-google-drive">Backup no Google Drive</a> (opcional, desligado por padrão)</td><td>Cópia das configurações e dados do eploc (o mesmo conteúdo do <a href="./geral/backup-arquivo">backup em arquivo</a>)</td><td>Pasta de dados do aplicativo na <strong>sua</strong> conta Google, direto do navegador para o Google.</td></tr><tr><td><a href="./funcionalidades/eproc-midias-link">Atalho PJe Mídias</a> (ligado por padrão)</td><td>O número do processo aberto, numa consulta como a que você faria à mão</td><td><code>midias.pje.jus.br</code>, usando a sua sessão.</td></tr><tr><td>Sincronização do navegador (se ligada no seu Chrome/Edge)</td><td>Configurações guardadas no armazenamento sincronizado</td><td>Conta do navegador (Google ou Microsoft).</td></tr><tr><td><a href="./geral/backup-arquivo">Backup em arquivo</a></td><td>O arquivo que você mesmo baixa</td><td>Seu computador.</td></tr></tbody></table><h2 id="google-drive-e-uso-limitado" tabindex="-1">Google Drive e &quot;Uso limitado&quot; <a class="header-anchor" href="#google-drive-e-uso-limitado" aria-label="Permalink to &quot;Google Drive e &quot;Uso limitado&quot;&quot;">​</a></h2><p>Ao conectar o Google Drive, o eploc pede só o escopo <code>drive.appdata</code>: acesso a uma pasta oculta, reservada ao próprio eploc, separada dos seus arquivos. A tela de consentimento do Google identifica o aplicativo como <strong>eploc</strong>. O uso dos dados recebidos das APIs do Google segue a Política de dados do usuário dos serviços de API do Google, incluindo os requisitos de Uso Limitado: os dados servem apenas ao backup e à sincronização, não são transferidos a terceiros, não são usados para publicidade, não são lidos por pessoas e não são usados para treinar modelos de inteligência artificial.</p><p>Você pode desconectar a conta nas configurações do eploc e revogar o acesso em <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">myaccount.google.com/permissions</a>.</p><h2 id="o-aviso-ler-e-alterar-todos-os-seus-dados" tabindex="-1">O aviso &quot;Ler e alterar todos os seus dados&quot; <a class="header-anchor" href="#o-aviso-ler-e-alterar-todos-os-seus-dados" aria-label="Permalink to &quot;O aviso &quot;Ler e alterar todos os seus dados&quot;&quot;">​</a></h2><p>O eploc só atua nos sites do eproc, SEI, RUPE e páginas do TJMG listados em <a href="./compatibilidade">Compatibilidade</a>. O navegador resume a lista longa de endereços <code>jus.br</code> nessa frase genérica. Ela pode reaparecer quando uma atualização inclui um novo tribunal, pedindo que você reative a extensão.</p><h2 id="seus-direitos-lgpd" tabindex="-1">Seus direitos (LGPD) <a class="header-anchor" href="#seus-direitos-lgpd" aria-label="Permalink to &quot;Seus direitos (LGPD)&quot;">​</a></h2><p>Como o eploc não envia seus dados ao desenvolvedor, você exerce diretamente, nas configurações da extensão e na sua conta Google, o acesso, a correção e a eliminação dos seus dados. Pedidos e dúvidas sobre privacidade: veja <a href="./contato">Contato</a>.</p>',21)]))}const g=o(s,[["render",t]]);export{m as __pageData,g as default};
